import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Criterio fondamentale del parallelismo","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffd.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffd.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/ffd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="criterio-fondamentale-del-parallelismo" tabindex="-1">Criterio fondamentale del parallelismo <a class="header-anchor" href="#criterio-fondamentale-del-parallelismo" aria-label="Permalink to “Criterio fondamentale del parallelismo”">​</a></h1><p>Se due rette tagliate da una trasversale formano angoli alterni interni uguali allora le due rette sono parallele</p><blockquote><p><strong>Nota:</strong> Facciamo la dimostrazione per assurdo</p></blockquote><p><strong>Ipotesi:</strong> <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="blue"><mtext>angolo\xA0</mtext><mn>1</mn><mo>=</mo><mtext>angolo\xA0</mtext><mn>2</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{\\text{angolo } 1 = \\text{angolo } 2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">angolo\xA0</span></span><span class="mord" style="color:blue;">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text" style="color:blue;"><span class="mord" style="color:blue;">angolo\xA0</span></span><span class="mord" style="color:blue;">2</span></span></span></span><strong>Tesi:</strong> <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="blue"><mi>a</mi><mo>∥</mo><mi>b</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{a \\parallel b}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="color:blue;">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">∥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="color:blue;">b</span></span></span></span></p><blockquote><p><strong>Dimostrazione:</strong> Supponiamo che le rette non siano parallele, ciò significa che, magari dopo qualche chilometro si incontreranno in un punto <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> (per questo ho messo il tratteggio). Ciò significa che si forma il <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>triangolo\xA0CAB</mtext></mrow><annotation encoding="application/x-tex">\\text{triangolo CAB}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">triangolo\xA0CAB</span></span></span></span></span> ed in questo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>triangolo\xA0CAB</mtext></mrow><annotation encoding="application/x-tex">\\text{triangolo CAB}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">triangolo\xA0CAB</span></span></span></span></span> l&#39;<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>angolo\xA0</mtext><mn>1</mn></mrow><annotation encoding="application/x-tex">\\text{angolo } 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">angolo\xA0</span></span><span class="mord">1</span></span></span></span> è esterno mentre l&#39;<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>angolo\xA0</mtext><mn>2</mn></mrow><annotation encoding="application/x-tex">\\text{angolo } 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">angolo\xA0</span></span><span class="mord">2</span></span></span></span> è interno non adiacente, quindi l&#39;<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>angolo\xA0</mtext><mn>1</mn></mrow><annotation encoding="application/x-tex">\\text{angolo } 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">angolo\xA0</span></span><span class="mord">1</span></span></span></span> deve essere maggiore dell&#39;<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>angolo\xA0</mtext><mn>2</mn></mrow><annotation encoding="application/x-tex">\\text{angolo } 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">angolo\xA0</span></span><span class="mord">2</span></span></span></span> contro l&#39;ipotesi. Ho negato l&#39;ipotesi quindi il criterio è vero.</p></blockquote><p>D&#39;ora in avanti per mostrare che due rette sono parallele basterà mostrare che gli angoli alterni interni sono uguali.</p><p>Equivalentemente potrai mostrare anche che sono uguali:</p><ul><li>gli angoli alterni esterni</li><li>gli angoli corrispondenti</li></ul><p>Sono supplementari (la loro somma è un angolo piatto):</p><ul><li>gli angoli coniugati interni</li><li>gli angoli coniugati esterni</li></ul>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};